-- Migration: create guide_sections
-- Backs the public /guide walkthrough page with editable content.
-- Public, read-only via RLS -- content is edited directly through the
-- Supabase Table Editor (service-role access bypasses RLS), not through the app.

CREATE TABLE IF NOT EXISTS guide_sections (
  id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  slug         TEXT        NOT NULL UNIQUE,
  group_label  TEXT        NOT NULL,
  title        TEXT        NOT NULL,
  dek          TEXT        NOT NULL DEFAULT '',
  blocks       JSONB       NOT NULL DEFAULT '[]',
  sort_order   INT         NOT NULL DEFAULT 0,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_guide_sections_sort ON guide_sections (sort_order);

ALTER TABLE guide_sections ENABLE ROW LEVEL SECURITY;

-- Public, read-only. No write policies on purpose -- edits happen via the
-- Supabase Table Editor (service role), same pattern as platform_admins.
CREATE POLICY "public_read_guide_sections"
  ON guide_sections FOR SELECT
  USING (true);

INSERT INTO guide_sections (slug, group_label, title, dek, blocks, sort_order) VALUES
  ($gsq$sign-in$gsq$, $gsq$Getting started$gsq$, $gsq$Signing in$gsq$, $gsq$You don't need a password — access is by email link.$gsq$, $gsq$[{"type": "ol", "items": ["Go to your admin login page (`/admin/login`), or click the settings icon in the bottom-right corner of your live site.", "Enter the email address your site is registered under.", "Check your inbox for a magic-link email and click it.", "You'll land back in the admin portal, signed in."]}, {"type": "callout", "variant": "tip", "label": "Good to know", "md": "You can only manage the site registered to your email. Signed in with the wrong one? You'll see an access message — sign out and try again with the correct address."}]$gsq$::jsonb, 0),
  ($gsq$dashboard-tour$gsq$, $gsq$Getting started$gsq$, $gsq$The dashboard, at a glance$gsq$, $gsq$Three things orient every visit: the section list on the left, the live preview, and Save.$gsq$, $gsq$[{"type": "ul", "items": ["**Left sidebar** — every editable part of your site. Click a section to open its editor.", "**Show/Hide Preview** — a live preview of your site next to the editor as you work.", "**View Live** — opens your published site in a new tab, exactly as visitors see it.", "**Save** — writes your changes. Nothing is public until you click it."]}, {"type": "text", "md": "The button reads **Saved ✓** once your edits are written — until then, it's safe to keep editing."}]$gsq$::jsonb, 1),
  ($gsq$branding$gsq$, $gsq$Look & feel$gsq$, $gsq$Branding$gsq$, $gsq$Your logo, brand colors, and overall site theme — these apply everywhere at once.$gsq$, $gsq$[{"type": "h3", "text": "Logo"}, {"type": "text", "md": "Upload a PNG or JPG, max 2MB. No logo yet? Your site shows your business initial in a colored badge instead."}, {"type": "h3", "text": "Brand colors"}, {"type": "swatches", "colors": ["#4EBCED", "#464E54", "#45899E"]}, {"type": "ul", "items": ["**Primary** — buttons, links, accents.", "**Secondary** — text, backgrounds, navigation.", "**Accent** — gradients, highlights, hover states."]}, {"type": "text", "md": "Pick with the color swatch or type a hex code directly."}, {"type": "h3", "text": "Site theme"}, {"type": "text", "md": "Sets your layout shape, fonts, and section styling all at once."}, {"type": "pills", "items": [{"label": "Professional", "selected": false}, {"label": "Creative", "selected": false}, {"label": "Wellness", "selected": false}, {"label": "Luxury", "selected": false}, {"label": "Minimalist", "selected": false}, {"label": "Innovative", "selected": false}, {"label": "Restorative", "selected": true}]}, {"type": "callout", "variant": "tip", "label": "Restorative theme only", "md": "Unlocks extended controls: Background, Text, and Muted colors (leave blank to fall back to the default look), plus Display, Body, and Accent fonts chosen from a small curated font list."}]$gsq$::jsonb, 2),
  ($gsq$navigation$gsq$, $gsq$Look & feel$gsq$, $gsq$Navigation$gsq$, $gsq$Control what appears in your header and footer.$gsq$, $gsq$[{"type": "h3", "text": "Header"}, {"type": "toggles", "items": [{"label": "Show logo", "on": true}, {"label": "Show business name", "on": true}, {"label": "Show tagline below logo", "on": false}]}, {"type": "h3", "text": "Secondary button"}, {"type": "text", "md": "An optional second button in the header — useful for a \"Donate\" link or an external booking page — with its own label and URL."}, {"type": "h3", "text": "Footer"}, {"type": "toggles", "items": [{"label": "Show logo", "on": true}, {"label": "Show business name", "on": true}]}, {"type": "text", "md": "Toggles shown in their default position — on when the pill is filled."}]$gsq$::jsonb, 3),
  ($gsq$hero$gsq$, $gsq$Page content$gsq$, $gsq$Hero section$gsq$, $gsq$The first thing visitors see. Edit your headline, subheadline, value statement, and both button labels.$gsq$, $gsq$[{"type": "h3", "text": "Media"}, {"type": "ul", "items": ["**Image or video** background — paste a video URL (YouTube links work) or upload an image.", "**Image ratio** — default (fixed height) or 16:9 widescreen.", "**Background mirror** — a faint, blurred copy of your hero image behind the section for extra depth."]}]$gsq$::jsonb, 4),
