ON CONFLICT (slug) DO UPDATE SET
  group_label = EXCLUDED.group_label,
  title       = EXCLUDED.title,
  dek         = EXCLUDED.dek,
  blocks      = EXCLUDED.blocks,
  sort_order  = EXCLUDED.sort_order,
  updated_at  = now();
